#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

banner "shubrt.me — Repo, Secrets, Deploy und Domain"

# ── Stage 1: GitHub-Repo anlegen und diesen Rechner berechtigen ───────────
stage "GitHub — Repo shubrt/me anlegen"
say "Das Repo muss unter dem Account shubrt entstehen; der lokale gh ist als"
say "s1njar angemeldet und kann dort keins anlegen. Du machst das im Browser,"
say "der Wizard übernimmt danach Einladung und Push."
open_url "https://github.com/new"
step "Owner: shubrt · Name: me · Sichtbarkeit nach Wunsch (public passt zum Portfolio)."
step "KEIN README, keine .gitignore, keine Lizenz anhaken — das Repo muss leer sein."
step "Repo anlegen, dann: Settings → Collaborators → Add people → s1njar → Rolle Admin."
note "Admin braucht es, damit dieser Rechner die Actions-Secrets setzen kann."
pause "Fertig? Enter drückt weiter."
say "Einladung annehmen und pushen …"
INVITE_ID=$(gh api user/repository_invitations --jq '.[] | select(.repository.full_name=="shubrt/me") | .id' 2>/dev/null | head -n1 || true)
if [[ -n "$INVITE_ID" ]]; then
  gh api --method PATCH "user/repository_invitations/$INVITE_ID" >/dev/null
  say "✓ Einladung angenommen."
else
  warn "Keine offene Einladung gefunden — vielleicht schon angenommen. Es geht weiter."
fi
if ! gh repo view shubrt/me >/dev/null 2>&1; then
  warn "shubrt/me ist für s1njar noch nicht sichtbar. Einladung prüfen, dann Wizard neu starten."
  exit 1
fi
git remote get-url origin >/dev/null 2>&1 || git remote add origin git@github.com:shubrt/me.git
say "✓ Remote origin: $(git remote get-url origin)"

# ── Stage 2: Cloudflare Account ID ────────────────────────────────────────
stage "Cloudflare — Account ID"
say "Die Deploy-Action braucht die Account ID als Secret."
open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages"
step "Auf der Workers-&-Pages-Übersicht steht rechts die Account ID — kopieren."
note "Alternativ: auf der Übersicht einer beliebigen Domain, rechte Spalte, API-Block."
ask CLOUDFLARE_ACCOUNT_ID "Account ID einfügen:"
write_env CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
set_secret CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"

# ── Stage 3: Cloudflare API Token ─────────────────────────────────────────
stage "Cloudflare — API Token für Deploys"
say "Ein Token, das nur Worker bearbeiten darf."
open_url "https://dash.cloudflare.com/profile/api-tokens"
step "Create Token → Vorlage 'Edit Cloudflare Workers' → Use template."
step "Account Resources: dein Account. Zone Resources kann auf 'All zones' bleiben."
step "Continue to summary → Create Token → Token kopieren (wird nur einmal gezeigt)."
ask_secret CLOUDFLARE_API_TOKEN "Token einfügen:"
write_env CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"
set_secret CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"

# ── Stage 4: Push und erster Deploy ───────────────────────────────────────
stage "Push und erster Deploy"
say "Der Push auf main stößt den Deploy-Workflow an (QA → Build → wrangler deploy)."
if confirm "Jetzt main nach shubrt/me pushen?"; then
  git push -u origin main
  say "✓ gepusht."
  sleep 4
  gh run list -R shubrt/me --workflow=deploy.yml -L 1 2>/dev/null || true
  open_url "https://github.com/shubrt/me/actions"
  step "Warte, bis der Deploy-Lauf grün ist (der erste Lauf legt den Worker shubrt-me an)."
  pause "Deploy grün? Enter drückt weiter."
else
  SKIPPED+=("git push -u origin main und ersten Deploy abwarten")
  warn "Push übersprungen — die restlichen Stages setzen einen Deploy voraus."
fi

# ── Stage 5: Custom Domain shubrt.me binden ───────────────────────────────
stage "Cloudflare — Domain shubrt.me an den Worker binden"
say "Einmalige Verknüpfung; die Zone shubrt.me muss im Account liegen."
open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages"
step "Worker 'shubrt-me' öffnen → Settings → Domains & Routes → Add → Custom domain."
step "Domain: shubrt.me → Add domain. DNS und Zertifikat richtet Cloudflare ein."
pause "Gebunden? Enter drückt weiter."

# ── Stage 6: Verifizieren ─────────────────────────────────────────────────
stage "Verifizieren"
say "Kurz warten, bis das Zertifikat aktiv ist (meist unter einer Minute)."
if command -v curl >/dev/null 2>&1; then
  STATUS=$(curl -s -o /dev/null -w '%{http_code}' --max-time 15 https://shubrt.me/ || echo "000")
  if [[ "$STATUS" == "200" ]]; then
    say "✓ https://shubrt.me antwortet mit 200."
  else
    warn "https://shubrt.me antwortet mit $STATUS — Zertifikat braucht evtl. noch einen Moment."
    SKIPPED+=("https://shubrt.me manuell prüfen")
  fi
fi
open_url "https://shubrt.me"
note "Täglich um 04:17 UTC baut der Cron neu und hält Repos und Version frisch."

finish
